#!/usr/bin/env bash
# ============================================================================
#  GSZ step114 — timed availability per plan (#19).
#  Each plan can carry an "available from / until" window. Outside it the plan
#  is hidden on the product page and rejected at checkout. Pills now carry a
#  stable data-idx, so hiding a plan never shifts checkout's plan index.
#  Files: adminCatalog.js, product_edit.ejs, products.js, product.ejs,
#  checkout.js + migration (product_plans.avail_from/avail_until).
#  Safe + idempotent; restores on any failure.
# ============================================================================
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step114-$TS"
TMP=$(mktemp -d)
FILES=(routes/adminCatalog.js views/admin/product_edit.ejs routes/products.js views/product.ejs routes/checkout.js)

echo "==> step114: timed availability per plan"
mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"

restore() {
  echo "!!  FAILED — restoring previous files"
  for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  pm2 restart gsz >/dev/null 2>&1 || true
  echo "!!  restored. no changes kept."
}
trap 'restore' ERR

echo "" | base64 -d > "$TMP/patch_step114.js"
echo ""   | base64 -d > "$TMP/migrate_step114.js"

echo "==> applying patches"
node "$TMP/patch_step114.js" "$GSZ"

echo "==> validating"
for f in routes/adminCatalog.js routes/products.js routes/checkout.js; do node --check "$GSZ/$f"; done
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/admin/product_edit.ejs','views/product.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"

echo "==> migrating db"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/migrate_step114.js" )

echo "==> restarting app"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
sleep 2

echo "==> health checks"
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
SLUG=$(cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node -e "require('dotenv/config');const{Pool}=require('pg');const p=new Pool({host:process.env.DB_HOST,port:+(process.env.DB_PORT||5432),user:process.env.DB_USER,password:process.env.DB_PASS,database:process.env.DB_NAME});p.query(\"SELECT slug FROM products WHERE active AND NOT hidden ORDER BY id LIMIT 1\").then(function(r){console.log(r.rows[0]?r.rows[0].slug:'');return p.end();}).catch(function(){console.log('')})" 2>/dev/null || true)
if [ -n "$SLUG" ]; then
  PC=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3900/product/$SLUG" || true)
  [ "$PC" = "200" ] && echo "    product page renders ($SLUG): OK" || { echo "    product page $SLUG -> $PC"; false; }
  CC=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:3900/checkout?p=$SLUG&plan=0&region=PK" || true)
  [ "$CC" = "200" ] && echo "    checkout renders ($SLUG): OK" || { echo "    checkout $SLUG -> $CC"; false; }
fi

trap - ERR
rm -rf "$TMP"
echo ""
echo "==> step114 OK ✅"
echo "    • Each plan in the product editor now has 'Available from' / 'Available until' (both optional)."
echo "    • Outside its window a plan is hidden on the storefront AND rejected at checkout."
echo "    • Hiding a plan never changes other plans' checkout links (stable data-idx)."
